    if(P==='puzzle'){const pls=[];for(let k=0;k<3;k++){const c=G.free(r,(x,y)=>pls.every(q=>Math.hypot(q.x-x,q.y-y)>3.5));if(c)pls.push(G.prop('plate',c[0],c[1],{plate:k,need:1}));}r.plates=pls;G.prop('chest',cx,cy,{loot:'puzzle',locked:'puzzle',hidden:1});}
