    {const g=dg.tiles[0];const cnt={};for(const row of g.frames[0])for(const ch of row)cnt[ch]=(cnt[ch]||0)+1;const top=Object.keys(cnt).sort((a,b)=>cnt[b]-cnt[a])[0];E.danger=complement(g.pal[top]||'#404040');}
