      if(P==='treasure'){M.prop('chest_rare',cx,cy,{loot:'rare'});for(let x=r.x0+1;x<r.x0+r.w-1;x+=3)if(M.walk(x,r.y0)&&!M.nearDoor(x,r.y0,1))M.obj('lookglass',x,r.y0,{solid:2});r.noSpawn=1;return true;}
