        const em=M.obj('emitter',x0,ey,{solid:2});const tg=M.obj('crystal',x0+8,my,{solid:2});const mk=(x,y,o,px,py)=>{const ob=M.obj(o?'mir_b':'mir_a',x,y,{solid:1,am:1,o});M.prop('plateM',px,py,{amp:ob});return ob;};
        let o1=M.ri(0,1),o2=M.ri(0,1);if(o1===want&&o2===want)o2=1-want;
        const m1=mk(x0+3,ey,o1,x0+2,ey),m2=mk(x0+3,my,o2,x0+2,my),m3=mk(x0+6,ey,M.ri(0,1),x0+6,ey+(my>ey?1:-1));
