      if(P==='lore'){M.prop('lore',cx,cy,{text:'The glassblower\'s notebook: \'Silvered the first pane today. Something in it waved before I did. I have not told the Queen.\''});M.obj('c',cx-3,cy,{solid:2});M.decal('shards_f',cx+2,cy+1);r.name='Glassblower\'s Studio';r.noSpawn=1;return true;}
