      const leaves=LIB.satellites(G,N.filter(r=>r.tag==='ruin'&&r!==ent&&r!==guard),5,(x,y)=>G.room({x0:x-4,y0:y-3,w:9,h:7,shape:G.pick(['rect','oct']),tag:'cellar'}),{hw:5,hh:4,dists:[9,11,13],sx:1.2});if(leaves.length<3)return 'leaves';
      // the buried chamber: no door at all, only the sinking sand above it
