      if(!bur)return 'buried';const host=G.pick(N.filter(r=>r!==ent&&r!==guard&&r!==oasis));const pt=G.portal(host,bur,{kind:'sinkspot'});pt.off=1;pt.sink=1;
      G.pace(path,leaves,{ends:['secret','treasure','lore','shrine','challenge'],rest:Math.floor(path.length/2),
        pools:[[['combat',3],['dunes',2],['ambush',1.5]],[['dunes',2],['combat',2],['trap',2],['turrets',1.5],['swarm',1]],[['elite',3],['turrets',2],['dunes',1.5]]]});
      bur.purpose='puzzle';bur.main=false;
      for(const r of N)if(!path.includes(r))r.purpose=r.tag==='dunes'?'dunes':G.pick(['combat','swarm','turrets','ruin','trap']);
      for(const r of N)if(r.tag==='dunes'&&!['entrance','miniboss','rest'].includes(r.purpose)&&r.purpose!=='dunes'&&G.chance(0.5))r.purpose='dunes';
      for(const r of N)if(r.tag!=='dunes'&&r.purpose==='dunes')r.purpose='ruin';
