      LIB.guard(G,[guard],ante,{hint:'The gate to the dry pool is barred by the raiders\' banners. The Dune King holds it.',opened:'The Dune King falls in the sand. His raiders\' gate swings open.'});
      for(const r of leaves){if(r.purpose==='treasure')LIB.lock(G,r,{hint:'A sealed caravan vault. The Dune King took its key.'});
        if(r.purpose==='secret')LIB.secret(G,r,{code:C.SECRET,style:'walk',found:'You walk straight through the dune. It was never there: a mirage, and behind it a hidden room.'});}
