      const leaves=LIB.satellites(G,N.filter(r=>r!==guard),5,(x,y)=>{if(band(x-5,x+5,y-4,y+4))return null;return G.room({x0:x-4,y0:y-3,w:9,h:7,shape:'rect',tag:'cell'});},{hw:5,hh:4,dists:[9,11,13],sx:1.25});if(leaves.length<4)return 'leaves';
      G.pace(path,leaves,{ends:['secret','puzzle','treasure','lore','shrine','challenge'],rest:Math.floor(path.length/2),pools:[[['chamber',3],['ambush',1.5]],[['chamber',2],['trap',2],['turrets',1.5],['swarm',1.5]],[['elite',3],['chamber',2],['turrets',1.5]]]});
      for(const r of N)if(!path.includes(r))r.purpose=G.pick(['chamber','chamber','swarm','turrets','trap']);
      for(const r of N)if(r.foldwall&&['rest','miniboss'].includes(r.purpose)){const tg=G.marks.folds.find(t=>t.room===r.id);if(tg){for(const [x,y] of tg.cells)G.set(x,y,C.FLOOR);G.marks.folds.splice(G.marks.folds.indexOf(tg),1);G.toggles.splice(G.toggles.indexOf(tg),1);r.foldwall=null;}}
      LIB.guard(G,[guard],ante,{hint:'The pagoda gate is a sealed scroll. The dragon painted on it is not on it any more; it is in the room with you.',opened:'The scroll dragon rolls itself up and lies still. The pagoda gate unrolls.'});
      for(const r of leaves){if(r.purpose==='treasure')LIB.lock(G,r,{hint:'The wish box is tied shut with a red cord. The dragon holds the end of it.'});
        if(r.purpose==='secret')LIB.secret(G,r,{code:C.SECRET,style:'ink',found:'Your wet footprint touches the painted door, and the ink runs, and it is a door.'});}
