      const a=E.art.ember_soul;if(a)for(const em of E.embers){const q=Math.min(1,(E.t-em.t)/4.5);b.globalAlpha=0.6+0.4*Math.sin(E.t*(8+q*20));b.drawImage(a[Math.floor(E.t*6)%a.length],sx(em.x)-4,sy(em.y)-6);b.globalAlpha=1;}
